editorial:
## Method and reasoning
At index i, each update contributes d·i+(x−L·d). Activate both coefficients at L and deactivate them at R+1. Prefix-sum the two difference arrays and evaluate the active linear function at each index. Use 64-bit products.

## Walk through the sample
The first update contributes 2, 5, 8 at positions 1–3. The second starts at position 3 with 4, then falls to 2 and 0. At their shared position the two active progressions sum to 12.

## Complexity
Time O(n+q), space O(n).

## Reference implementation
~~~
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n + 1), slope(n + 2), intercept(n + 2);
    for (int i = 1; i <= n; ++i)
        cin >> a[i];
    while (q--) {
        int l, r;
        long long x, d;
        cin >> l >> r >> x >> d;
        long long b = x - l * d;
        slope[l] += d;
        slope[r + 1] -= d;
        intercept[l] += b;
        intercept[r + 1] -= b;
    }
    long long m = 0, b = 0;
    for (int i = 1; i <= n; ++i) {
        m += slope[i];
        b += intercept[i];
        cout << a[i] + i * m + b << (i == n ? '\n' : ' ');
    }
}
~~~
